<?php if(!defined("main_index_files")){http_response_code(503);echo"503";exit;}if(!$system_v["login"]["valid"]){echo"<div class=\"msg warn\">로그인 필요</div>";return;}$prd=(int)($_GET["prd"]??0);$to=(int)($_GET["to"]??0);global $sql;$p=$sql->one("SELECT prd_title,prd_seller,prd_price FROM products WHERE prd_number=?","i",[$prd]);$u=$sql->one("SELECT acc_id FROM users WHERE acc_number=?","i",[$to]);if(!$p||!$u){echo"<div class=\"msg err\">정보 없음</div>";return;}$exists=$sql->one("SELECT rv_id FROM reviews WHERE rv_writer=? AND rv_prd=?","ii",[(int)$system_v["login"]["number"],$prd]);if($exists){echo"<div class=\"msg ok\">이미 평가 완료</div>";return;}?><h1 class="h1">거래 평가</h1><div class="card"><p>상품: <?=e($p["prd_title"])?> · 대상: <?=e($u["acc_id"])?></p><form id="rv" onsubmit="return false"><input type="hidden" name="token" value="<?=e($system_v["token"])?>"><input type="hidden" name="mode" value="leave_review"><input type="hidden" name="prd" value="<?=$prd?>"><input type="hidden" name="to" value="<?=$to?>"><label>평점 (0~100)</label><input name="score" inputmode="numeric" value="50"><label>한줄평 (선택)</label><input name="comment" maxlength="300"><div style="margin-top:10px"><button class="btn primary">평가 제출</button></div></form></div><script>document.querySelector("#rv .btn.primary").addEventListener("click",function(){Jn.req("/service_bridge.php",{form:new FormData(document.getElementById("rv"))}).then(function(j){Jn.handleRes(j,function(){location.href="/?mode=mypage";});});});</script>